"""Idempotency store for POST /payments. See docs/adr/0004."""
import hashlib
import json

TTL_SECONDS = 24 * 60 * 60  # ADR-0004: replay window


class IdempotencyConflict(Exception):
    """Same key reused with a different request body (ADR-0004 rule 4)."""


def _store_key(merchant_id, key):
    return f"idem:{merchant_id}:{key}"


def _fingerprint(body):
    return hashlib.sha256(json.dumps(body, sort_keys=True).encode()).hexdigest()


def lookup(redis, merchant_id, key, body):
    raw = redis.get(_store_key(merchant_id, key))
    if raw is None:
        return None
    entry = json.loads(raw)
    if entry["fingerprint"] != _fingerprint(body):
        raise IdempotencyConflict(key)
    return entry["status"], entry["response"]


def save(redis, merchant_id, key, body, status, response):
    entry = {"fingerprint": _fingerprint(body), "status": status, "response": response}
    redis.set(_store_key(merchant_id, key), json.dumps(entry), ex=TTL_SECONDS)

