import pytest

from services.payments import idempotency


class FakeRedis:
    def __init__(self):
        self.data = {}
        self.ttls = {}

    def get(self, k):
        return self.data.get(k)

    def set(self, k, v, ex=None):
        self.data[k] = v
        self.ttls[k] = ex


def test_replay_returns_stored_response():
    r = FakeRedis()
    idempotency.save(r, "m_1", "k1", {"amount": 500}, 201, {"id": "pay_1"})
    assert idempotency.lookup(r, "m_1", "k1", {"amount": 500}) == (201, {"id": "pay_1"})


def test_keys_are_scoped_per_merchant():
    r = FakeRedis()
    idempotency.save(r, "m_1", "k1", {"amount": 500}, 201, {"id": "pay_1"})
    assert idempotency.lookup(r, "m_2", "k1", {"amount": 500}) is None


def test_mismatched_body_raises_conflict():
    r = FakeRedis()
    idempotency.save(r, "m_1", "k1", {"amount": 500}, 201, {"id": "pay_1"})
    with pytest.raises(idempotency.IdempotencyConflict):
        idempotency.lookup(r, "m_1", "k1", {"amount": 900})


def test_ttl_is_24_hours():
    r = FakeRedis()
    idempotency.save(r, "m_1", "k1", {"amount": 500}, 201, {"id": "pay_1"})
    assert r.ttls["idem:m_1:k1"] == 86400

