import logging

from services.payments import idempotency
from services.payments.ledger import record_payment
from services.payments.redis_client import redis

log = logging.getLogger(__name__)


def create_payment(request):
    key = request.headers.get("Idempotency-Key")
    if not key:
        return 400, {"error": "Idempotency-Key header is required"}
    body = request.json()
    try:
        cached = idempotency.lookup(redis, request.merchant_id, key, body)
    except idempotency.IdempotencyConflict:
        return 422, {"error": "Idempotency-Key reused with a different request body"}
    if cached is not None:
        log.debug("idempotency hit merchant=%s key=%s", request.merchant_id, key)
        return cached
    payment = record_payment(request.merchant_id, body)
    idempotency.save(redis, request.merchant_id, key, body, 201, payment)
    log.debug("payment created merchant=%s id=%s", request.merchant_id, payment["id"])
    return 201, payment
